drop policy if exists enforced_project_scope on public.project_work_section_templates;
create policy enforced_project_scope on public.project_work_section_templates as restrictive for all to authenticated using (voltmaster_private.security_project_scope(project_id)) with check (voltmaster_private.security_project_scope(project_id));
drop policy if exists enforced_project_scope on public.project_work_section_template_items;
create policy enforced_project_scope on public.project_work_section_template_items as restrictive for all to authenticated using (exists(select 1 from public.project_work_section_templates t where t.id=template_id and voltmaster_private.security_project_scope(t.project_id))) with check (exists(select 1 from public.project_work_section_templates t where t.id=template_id and voltmaster_private.security_project_scope(t.project_id)));
drop policy if exists enforced_project_scope on public.project_work_section_template_materials;
create policy enforced_project_scope on public.project_work_section_template_materials as restrictive for all to authenticated using (exists(select 1 from public.project_work_section_template_items i join public.project_work_section_templates t on t.id=i.template_id where i.id=template_item_id and voltmaster_private.security_project_scope(t.project_id))) with check (exists(select 1 from public.project_work_section_template_items i join public.project_work_section_templates t on t.id=i.template_id where i.id=template_item_id and voltmaster_private.security_project_scope(t.project_id)));
